16	class OrcaPrinterBackend : public IPrinterBackend
17	{
18	public:
19	    // `spools` is the app-level store the rest of the shell already shares;
20	    // without one this backend reports a printer's spools as unknown and
21	    // refuses to change them.
22	    OrcaPrinterBackend(Plater& plater, PrinterCatalog catalog, Workspace::SpoolStore* spools);
23	
24	    std::vector<CatalogPrinter>    search_catalog(const std::string& text, std::size_t limit) const override;
25	    std::vector<DiscoveredPrinter> network_printers() const override;
26	    std::vector<SavedPrinter>      saved_printers() const override;
27	
28	    std::string add_printer(const AddPrinterRequest& request, SavedPrinter& added) override;
29	    std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& changed) override;
30	
31	    void run_manual_setup() override;
32	    void open_printer_settings(const std::string& name) override;
33	
34	private:
35	    const CatalogPrinter* model_of(const std::string& printer_name) const;
36	
37	    Plater&                     m_plater;
38	    PrinterCatalog              m_catalog;
39	    Workspace::SpoolStore*      m_spools{nullptr};
40	    // One entry per model, built once from the catalogue's per-variant
41	    // candidates: the panel proposes printers, and a nozzle is a fact about
42	    // the printer rather than a printer of its own.
43	    std::vector<CatalogPrinter> m_models;
44	};
