26	std::string lowered(std::string text)
27	{
28	    std::transform(text.begin(), text.end(), text.begin(),
29	                   [](unsigned char letter) { return static_cast<char>(std::tolower(letter)); });
30	    return text;
31	}
32	
33	// Every word of the query has to appear somewhere in the entry, so "bambu a1
34	// mini" narrows rather than widens, and a word nobody uses finds nothing.
35	bool matches(const std::string& haystack, const std::vector<std::string>& words)
36	{
37	    return std::all_of(words.begin(), words.end(),
38	                       [&haystack](const std::string& word) { return haystack.find(word) != std::string::npos; });
39	}
40	
41	std::vector<std::string> words_of(const std::string& text)
42	{
43	    std::vector<std::string> words;
44	    std::istringstream       stream(lowered(text));
45	    std::string              word;
46	    while (stream >> word) {
47	        // "0.4mm", "a1," and "(combo)" are the same words with punctuation.
48	        word.erase(std::remove_if(word.begin(), word.end(),
49	                                  [](unsigned char letter) { return std::ispunct(letter) && letter != '.'; }),
50	                   word.end());
51	        if (!word.empty())
52	            words.push_back(word);
53	    }
54	    return words;
55	}
56	
57	CatalogPrinter entry_of(const PrinterCandidate& candidate)
58	{
59	    CatalogPrinter printer;
60	    printer.id               = candidate.vendor_id + "/" + candidate.model_id;
61	    printer.vendor_id        = candidate.vendor_id;
62	    printer.vendor_name      = candidate.vendor_name;
63	    printer.model_id         = candidate.model_id;
64	    printer.model_name       = candidate.model_name;
65	    printer.device_model_id  = candidate.device_model_id;
66	    printer.build_volume     = candidate.build_volume;
67	    printer.picture          = candidate.artwork_path;
68	    printer.default_plate    = candidate.default_plate;
69	    printer.default_material = candidate.default_material;
70	    return printer;
71	}
72	
73	double nozzle_of(const std::string& variant)
74	{
75	    try {
76	        return std::stod(variant);
77	    } catch (const std::exception&) {
78	        return 0.;
79	    }
80	}
