84	OrcaPrinterBackend::OrcaPrinterBackend(Plater& plater, PrinterCatalog catalog, Workspace::SpoolStore* spools)
85	    : m_plater(plater), m_catalog(std::move(catalog)), m_spools(spools)
86	{
87	    // The catalogue carries one candidate per model and nozzle; a person has
88	    // one printer with one nozzle, so fold the variants into the model and
89	    // keep the sizes it ships as a fact about it.
90	    for (const PrinterCandidate& candidate : m_catalog.candidates()) {
91	        const std::string id = candidate.vendor_id + "/" + candidate.model_id;
92	        const auto        known = std::find_if(m_models.begin(), m_models.end(),
93	                                               [&id](const CatalogPrinter& printer) { return printer.id == id; });
94	        CatalogPrinter&   printer = known == m_models.end() ? m_models.emplace_back(entry_of(candidate)) : *known;
95	        const double      nozzle  = nozzle_of(candidate.variant);
96	        if (nozzle > 0. && std::find(printer.nozzles.begin(), printer.nozzles.end(), nozzle) == printer.nozzles.end())
97	            printer.nozzles.push_back(nozzle);
98	    }
99	    for (CatalogPrinter& printer : m_models)
100	        std::sort(printer.nozzles.begin(), printer.nozzles.end());
101	}
102	
103	std::vector<CatalogPrinter> OrcaPrinterBackend::search_catalog(const std::string& text, std::size_t limit) const
104	{
105	    const std::vector<std::string> words = words_of(text);
106	    std::vector<CatalogPrinter>    found;
107	    if (words.empty())
108	        return found;
109	
110	    for (const CatalogPrinter& printer : m_models) {
111	        if (found.size() >= limit)
112	            break;
113	        const std::string haystack =
114	            lowered(printer.vendor_name + " " + printer.model_name + " " + printer.build_volume + " " + printer.device_model_id);
115	        if (matches(haystack, words))
116	            found.push_back(printer);
117	    }
118	    return found;
119	}
