123	const CatalogPrinter* OrcaPrinterBackend::model_of(const std::string& printer_name) const
124	{
125	    const PresetBundle* presets = wxGetApp().preset_bundle;
126	    if (presets == nullptr)
127	        return nullptr;
128	    const Preset* preset = presets->printers.find_preset(printer_name, false);
129	    if (preset == nullptr)
130	        return nullptr;
131	    const std::string model = preset->config.opt_string("printer_model");
132	    const auto        found = std::find_if(m_models.begin(), m_models.end(),
133	                                           [&model](const CatalogPrinter& printer) { return printer.model_id == model; });
134	    return found == m_models.end() ? nullptr : &*found;
135	}
