137	std::vector<SavedPrinter> OrcaPrinterBackend::saved_printers() const
138	{
139	    const std::vector<DiscoveredPrinter> network = discover_printers(/*include_unreachable=*/true);
140	    const PresetBundle*                  presets = wxGetApp().preset_bundle;
141	
142	    std::vector<SavedPrinter> printers;
143	    for (const Printers::NamedPrinter& named : Printers::named_printers()) {
144	        SavedPrinter saved;
145	        saved.name      = named.name;
146	        saved.device_id = named.device_id;
147	        saved.nozzle    = named.nozzle;
148	
149	        if (const CatalogPrinter* model = model_of(named.name)) {
150	            saved.model     = model->vendor_name + " " + model->model_name;
151	            saved.model_id  = model->model_id;
152	            saved.vendor_id = model->vendor_id;
153	            saved.picture   = model->picture;
154	            saved.nozzles   = model->nozzles;
155	            saved.plate     = model->default_plate;
156	        }
157	        if (presets != nullptr) {
158	            if (const Preset* preset = presets->printers.find_preset(named.name, false)) {
159	                const std::string plate = preset->config.opt_string("default_bed_type");
160	                if (!plate.empty())
161	                    saved.plate = plate;
162	            }
163	        }
164	
165	        // What the machine says beats what the profile assumed.
166	        const auto found = std::find_if(network.begin(), network.end(),
167	                                        [&saved](const DiscoveredPrinter& device) { return device.stable_id == saved.device_id; });
168	        if (found != network.end() && !saved.device_id.empty()) {
169	            saved.connected = found->connected;
170	            saved.activity  = found->activity == PrinterActivity::Printing ? "printing" :
171	                              found->activity == PrinterActivity::Idle     ? "idle" :
172	                                                                            "offline";
173	            saved.ams       = found->ams_name;
174	            for (const DiscoveredPrinter::Spool& spool : found->spools)
175	                saved.spools.push_back(PrinterSpool{spool.name, spool.material, spool.colour});
176	        } else if (m_spools != nullptr) {
177	            // Not connected, or never was: what this app remembers is loaded.
178	            for (const Workspace::Spool& spool : m_spools->spools_for(named.name))
179	                saved.spools.push_back(PrinterSpool{spool.name, spool.filament_preset, spool.colour});
180	        }
181	        printers.push_back(std::move(saved));
182	    }
183	    return printers;
184	}
