186	std::string OrcaPrinterBackend::add_printer(const AddPrinterRequest& request, SavedPrinter& added)
187	{
188	    std::string error;
189	    if (!SetupCommands::install_and_select_printer(m_plater, request.vendor_id, request.model_id, request.variant,
190	                                                  request.material, error))
191	        return error.empty() ? std::string("This printer could not be installed.") : error;
192	
193	    const std::string name =
194	        Printers::add_named_printer(m_plater, request.name.empty() ? request.model_id : request.name, request.device_id);
195	
196	    if (!request.access_code.empty() && !request.device_id.empty()) {
197	        wxString connect_error;
198	        // The printer is saved either way: a code that does not take is a
199	        // connection that has to be made again, not a printer that was lost.
200	        if (!SetupCommands::set_printer_access_code(request.device_id, request.access_code, connect_error)) {
201	            for (const SavedPrinter& saved : saved_printers())
202	                if (saved.name == name)
203	                    added = saved;
204	            return connect_error.empty() ? std::string("That access code was not accepted.") : connect_error.ToStdString();
205	        }
206	    }
207	
208	    for (const SavedPrinter& saved : saved_printers())
209	        if (saved.name == name)
210	            added = saved;
211	    return {};
212	}
213	
214	std::string OrcaPrinterBackend::change_printer(const ChangePrinterRequest& request, SavedPrinter& changed)
215	{
216	    std::vector<SavedPrinter> printers = saved_printers();
217	    const auto                found    = std::find_if(printers.begin(), printers.end(),
218	                                                      [&request](const SavedPrinter& saved) { return saved.name == request.name; });
219	    if (found == printers.end())
220	        return "This app no longer has a printer called \"" + request.name + "\".";
221	
222	    if (request.nozzle) {
223	        const PrinterCandidate* variant = nullptr;
224	        for (const PrinterCandidate& candidate : m_catalog.candidates())
225	            if (candidate.model_id == found->model_id && nozzle_of(candidate.variant) == *request.nozzle)
226	                variant = &candidate;
227	        if (variant == nullptr)
228	            return found->model.empty() ? std::string("This printer does not come with that nozzle size.") :
229	                                          "The " + found->model + " does not come with that nozzle size.";
230	        const wxString problem = Printers::change_named_printer_nozzle(m_plater, request.name, variant->preset_name);
231	        if (!problem.empty())
232	            return problem.ToStdString();
233	    }
234	
235	    if (request.spools) {
236	        if (m_spools == nullptr)
237	            return "This app cannot record spools yet.";
238	        for (const Workspace::Spool& spool : m_spools->spools_for(request.name))
239	            m_spools->remove(spool.id);
240	        for (const PrinterSpool& spool : *request.spools) {
241	            Workspace::Spool record;
242	            record.printer_preset  = request.name;
243	            record.filament_preset = spool.material;
244	            record.name            = spool.name;
245	            record.colour          = spool.colour;
246	            m_spools->add(std::move(record));
247	        }
248	    }
249	
250	    if (request.access_code) {
251	        if (found->device_id.empty())
252	            return "This printer is not one this app found on your network, so it has no access code.";
253	        wxString code_error;
254	        if (!SetupCommands::set_printer_access_code(found->device_id, *request.access_code, code_error))
255	            return code_error.empty() ? std::string("That access code was not accepted.") : code_error.ToStdString();
256	    }
257	
258	    for (const SavedPrinter& saved : saved_printers())
259	        if (saved.name == request.name)
260	            changed = saved;
261	    return {};
262	}
