264	void OrcaPrinterBackend::run_manual_setup()
265	{
266	    // OrcaSlicer's own printer wizard, unchanged, and the printers it
267	    // installs are saved under their own names the way the old dialog's
268	    // manual path did.
269	    const Printers::VendorMap before = wxGetApp().app_config->vendors();
270	    // False when the person closed the wizard without applying it.
271	    if (!wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS))
272	        return;
273	    Printers::name_installed_printers(m_plater, before);
274	}
