10	// What a printer is doing, as far as this application can see. Offline is a
11	// statement about what was observed, not a claim that the machine is off.
12	enum class PrinterActivity : std::uint8_t { Offline, Idle, Printing };
13	
14	struct DiscoveredPrinter
15	{
16	    std::string stable_id;
17	    std::string name;
18	    std::string ip_address;
19	    std::string device_model_id;
20	    std::string connection;
21	    bool connected{false};
22	    PrinterActivity activity{PrinterActivity::Offline};
23	    // When the device last said anything, as milliseconds since the epoch.
24	    // Zero when it never has: a printer known from a previous session but not
25	    // heard from since is a real state, and a fabricated timestamp is not.
26	    std::int64_t observed_at_ms{0};
27	    // What the printer reported about itself; zero or empty when it has not said.
28	    double nozzle_diameter{0.};
29	    std::string ams_name;
30	    struct Spool
31	    {
32	        std::string name;
33	        std::string colour;   // "#RRGGBB"
34	        std::string material; // the filament type, such as PLA; may be empty
35	    };
36	    std::vector<Spool> spools;
37	    // The machine the app is working with, as Orca's device manager has it.
38	    bool selected{false};
39	    // The job in progress; -1 and empty when it has not said.
40	    int         progress_percent{-1};
41	    std::string job;
42	    // Degrees Celsius, as last reported; absent when it has not said.
43	    std::optional<double> nozzle_temperature;
44	    std::optional<double> bed_temperature;
45	};
46	
47	struct PrinterCandidate
48	{
49	    // Opaque, session-local identifier for one model and nozzle variant.
50	    std::string id;
51	    std::string vendor_id;
52	    std::string vendor_name;
53	    std::string model_id;
54	    std::string model_name;
55	    std::string device_model_id;
56	    std::string variant;
57	    std::string preset_name;
58	    std::string build_volume;
59	    std::string default_material;
60	    std::string default_plate;
61	    std::string artwork_path;
62	};
