3	// What the printer conversation is allowed to know and do about printers.
4	//
5	// A printer is app-level, not project-level, so this follows Home rather than
6	// the workspace contract: the surface owns a narrow interface, and one Orca
7	// implementation behind it calls the existing owners -- PrinterCatalog,
8	// PrinterDiscovery, Printers::, SetupCommands::, SpoolStore. GUI-free and
9	// Orca-free so the conversation can be tested without either.
10	
11	#include "PrinterSetupTypes.hpp"
12	
13	#include <optional>
14	#include <string>
15	#include <vector>
16	
17	namespace Slic3r::GUI::JusPrin::PrinterSetup {
18	
19	// One spool as a printer reports it or as this app remembers it.
20	struct PrinterSpool
21	{
22	    std::string name;
23	    std::string material;
24	    std::string colour; // "#RRGGBB", empty when unknown
25	};
26	
27	// A printer already saved in this app: an Orca user printer profile, with the
28	// facts it was set up with.
29	struct SavedPrinter
30	{
31	    std::string               name;
32	    std::string               device_id;
33	    std::string               model;        // display model name
34	    std::string               model_id;     // profile model id
35	    std::string               vendor_id;
36	    std::string               picture;      // cover image path, may be empty
37	    double                    nozzle{0.};
38	    std::vector<double>       nozzles;      // sizes this model ships
39	    std::string               plate;        // untranslated plate name
40	    std::string               ams;          // "AMS lite", "AMS", or empty
41	    std::vector<PrinterSpool> spools;
42	    std::string               activity;     // offline, idle, printing, or empty
43	    bool                      connected{false};
44	};
45	
46	// What the packaged profiles offer, one entry per model.
47	struct CatalogPrinter
48	{
49	    std::string         id; // catalogue id, stable for this session
50	    std::string         vendor_id;
51	    std::string         vendor_name;
52	    std::string         model_id;
53	    std::string         model_name;
54	    std::string         device_model_id;
55	    std::string         build_volume; // "180 × 180 × 180 mm"
56	    std::string         picture;
57	    std::string         default_plate;
58	    std::string         default_material;
59	    std::vector<double> nozzles;
60	};
61	
62	// Everything the app needs to save a printer the person has just agreed to.
63	struct AddPrinterRequest
64	{
65	    std::string vendor_id;
66	    std::string model_id;
67	    std::string variant;  // nozzle size as the profile spells it, e.g. "0.4"
68	    std::string material; // default filament preset, may be empty
69	    std::string name;     // display name; empty uses the model name
70	    std::string device_id;    // a discovered printer's id, when this is one
71	    std::string access_code;  // optional, saved only when a device was named
72	};
73	
74	// A correction to a printer that already exists. Every field is optional;
75	// what is left out stays as it is.
76	struct ChangePrinterRequest
77	{
78	    std::string                  name; // the saved printer to change
79	    std::optional<double>        nozzle;
80	    std::optional<std::string>   access_code;
81	    std::optional<std::vector<PrinterSpool>> spools;
82	};
