84	class IPrinterBackend
85	{
86	public:
87	    virtual ~IPrinterBackend() = default;
88	
89	    // Reads.
90	    virtual std::vector<CatalogPrinter>   search_catalog(const std::string& text, std::size_t limit) const = 0;
91	    virtual std::vector<DiscoveredPrinter> network_printers() const = 0;
92	    virtual std::vector<SavedPrinter>     saved_printers() const = 0;
93	
94	    // Writes. Each returns an empty string on success, or a message written
95	    // for the person explaining what stopped it.
96	    virtual std::string add_printer(const AddPrinterRequest& request, SavedPrinter& added) = 0;
97	    virtual std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& changed) = 0;
98	
99	    // The manual paths behind "Set it up myself": OrcaSlicer's own printer
100	    // wizard for a new printer, its printer settings for an existing one.
101	    virtual void run_manual_setup() = 0;
102	    virtual void open_printer_settings(const std::string& name) = 0;
103	};
