31	// One row of the pinned card. An empty value is the em dash the panel draws
32	// for a fact nobody has stated yet.
33	struct PinnedFact
34	{
35	    std::string value;
36	    // settled: known, from the printer or the person. assumed: the agent's
37	    // stated guess. changed: altered in this session, and the panel says so.
38	    std::string provenance{"settled"};
39	    std::string swatch; // "#RRGGBB" of the first loaded spool, when there is one
40	};
