57	// Everything the panel needs from its owner. The panel is the only
58	// implementation; the tests use a recording fake.
59	class IConversationHost
60	{
61	public:
62	    virtual ~IConversationHost() = default;
63	
64	    // A muted line in the thread, such as "Use this" · 01P00A3B.
65	    virtual void post_note(const std::string& text) = 0;
66	    // The agent answers next, with no user message in the thread: the person
67	    // tapped something rather than typing it.
68	    virtual void ask_agent(const std::string& prompt) = 0;
69	    // The pinned card, the chips and the thread's own cards have changed.
70	    virtual void session_changed() = 0;
71	    // The panel is done: back to the printer list.
72	    virtual void close_panel() = 0;
73	    // A printer was saved; Home's list is out of date.
74	    virtual void printers_changed() = 0;
75	};
