128	
129	    ConversationMode m_mode{ConversationMode::Add};
130	    std::string      m_printer_name;
131	    SavedPrinter     m_printer; // the Change session's subject
132	
133	    // Pinned facts, in the order the panel draws them.
134	    PinnedFact m_printer_fact, m_nozzle, m_plate, m_filament;
135	
136	    PrinterProposal m_proposal;
137	    // The cards the agent has drawn in the thread, oldest first.
138	    nlohmann::json  m_blocks   = nlohmann::json::array();
139	    nlohmann::json  m_chips    = nlohmann::json::array();
