23	std::string nozzle_text(double nozzle)
24	{
25	    if (nozzle <= 0.)
26	        return {};
27	    std::ostringstream out;
28	    out.precision(2);
29	    out << std::fixed << nozzle;
30	    std::string text = out.str();
31	    while (text.size() > 3 && text.back() == '0')
32	        text.pop_back();
33	    return text + " mm";
34	}
35	
36	// The profile's own spelling of a nozzle size, as the variant is named.
37	std::string variant_text(double nozzle)
38	{
39	    std::ostringstream out;
40	    out.precision(1);
41	    out << std::fixed << nozzle;
42	    return out.str();
43	}
44	
45	std::string picture_data_url(const std::string& path)
46	{
47	    if (path.empty())
48	        return {};
49	    std::ifstream file(std::filesystem::u8path(path), std::ios::binary);
50	    if (!file.good())
51	        return {};
52	    std::ostringstream bytes;
53	    bytes << file.rdbuf();
54	    const std::string data = bytes.str();
55	    if (data.empty())
56	        return {};
57	    return "data:image/png;base64," + base64_encode(data);
58	}
59	
60	json fact_json(const PinnedFact& fact)
61	{
62	    json value{{"value", fact.value}, {"provenance", fact.provenance}};
63	    if (!fact.swatch.empty())
64	        value["swatch"] = fact.swatch;
65	    return value;
66	}
