68	// What a printer says it has loaded, as one line: "AMS lite · PLA Matte + 3".
69	std::string spool_summary(const std::string& ams, const std::vector<PrinterSpool>& spools)
70	{
71	    if (spools.empty())
72	        return ams.empty() ? std::string() : ams;
73	    std::string summary = spools.front().name.empty() ? spools.front().material : spools.front().name;
74	    if (spools.size() > 1)
75	        summary += " + " + std::to_string(spools.size() - 1);
76	    return ams.empty() ? summary : ams + " · " + summary;
77	}
