90	void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
91	{
92	    m_mode         = mode;
93	    m_printer_name = printer_name;
94	    m_printer      = {};
95	    m_proposal     = {};
96	    m_blocks       = json::array();
97	    m_chips        = json::array();
98	    m_chip_hint.clear();
99	    m_next_block = 1;
100	    m_catalog.clear();
101	    m_network.clear();
102	
103	    m_printer_fact = m_nozzle = m_plate = m_filament = {};
104	    // A printer this app has not saved cannot be changed, and the header's
105	    // menu can name one: a system profile is selected until the person adds
106	    // a printer of their own. Adding one is what there is to do.
107	    if (m_mode == ConversationMode::Change) {
108	        const std::vector<SavedPrinter> saved = m_backend.saved_printers();
109	        if (std::none_of(saved.begin(), saved.end(),
110	                         [this](const SavedPrinter& printer) { return printer.name == m_printer_name; })) {
111	            m_mode = ConversationMode::Add;
112	            m_printer_name.clear();
113	        }
114	    }
115	
116	    if (m_mode == ConversationMode::Change) {
117	        read_saved_printer();
118	        m_placeholder = "e.g. \"I swapped the plate\" or \"is it connected?\"";
119	    } else {
120	        refresh_network();
121	        m_placeholder = "e.g. \"bambu a1 mini\" or \"not sure, the small one\"";
122	        // A photo is the fastest way in, and the printers already on the
123	        // network are the fastest of all. Both belong under the opening,
124	        // where the person is deciding what to say.
125	        m_blocks.push_back(json{{"id", "b" + std::to_string(m_next_block++)},
126	                                {"seq", m_blocks.size() + 1},
127	                                {"afterMessageId", ""},
128	                                {"kind", "tip"}});
129	        if (!m_network.empty()) {
130	            json found = json::array();
131	            for (const DiscoveredPrinter& printer : m_network)
132	                found.push_back(json{{"deviceId", printer.stable_id},
133	                                     {"name", printer.name},
134	                                     {"serial", printer.stable_id},
135	                                     {"online", printer.connected}});
136	            m_blocks.push_back(json{{"id", "b" + std::to_string(m_next_block++)},
137	                                    {"seq", m_blocks.size() + 1},
138	                                    {"afterMessageId", ""},
139	                                    {"kind", "network"},
140	                                    {"printers", std::move(found)}});
141	        }
142	    }
143	    m_host.session_changed();
144	}
