154	void PrinterConversation::read_saved_printer()
155	{
156	    for (const SavedPrinter& saved : m_backend.saved_printers())
157	        if (saved.name == m_printer_name)
158	            m_printer = saved;
159	
160	    m_printer_fact = {m_printer.name.empty() ? m_printer_name : m_printer.name, "settled", {}};
161	    m_nozzle       = {nozzle_text(m_printer.nozzle), "settled", {}};
162	    // The plate a printer is set up with is a starting point rather than a
163	    // reading: it is the plate its profile ships with until a project says
164	    // otherwise.
165	    m_plate        = {m_printer.plate, "assumed", {}};
166	    m_filament     = {spool_summary(m_printer.ams, m_printer.spools), "settled",
167	                      m_printer.spools.empty() ? std::string() : m_printer.spools.front().colour};
168	}
