175	Agent::AgentSessionProfile PrinterConversation::profile() const
176	{
177	    Agent::AgentSessionProfile profile;
178	    profile.tool_names        = session_tools();
179	    // This conversation is about a machine, not about the open project.
180	    profile.include_workspace = false;
181	
182	    std::ostringstream instructions;
183	    instructions
184	        << "You are JusPrin's printer assistant, in the printer panel on the Home screen. "
185	           "Keep every turn to one or two short sentences of plain language: no lists, no headings, and never read the pinned card back. "
186	           "The panel above the thread pins four facts -- Printer, Nozzle, Plate, Filament -- and you fill them only by calling printer_propose. "
187	           "Offer what to do next with printer_suggest: up to three specific actions such as \"Use 0.3 mm layers\", never a bare Yes or No. ";
188	
189	    if (m_mode == ConversationMode::Add) {
190	        instructions
191	            << "The person is adding a printer to this app.\n"
192	               "Finding it: search the packaged profiles with printer_catalog_search using the person's own words. A photo of the printer, "
193	               "its nameplate or its box is evidence -- read it and search for what you see.\n"
194	               "One clear match: call printer_propose with that printer alone, assuming a 0.4 mm nozzle, the plate the model ships with and "
195	               "PLA unless the person or the photo says otherwise, then say in one sentence what you assumed.\n"
196	               "Two or three that fit: call printer_propose with all of them and say what tells them apart, so the person can answer.\n"
197	               "Nothing fits: say so and ask for the one detail that would settle it.\n"
198	               "The person adds the printer by tapping \"Add this printer\" on the card you drew. Never say a printer has been added, and "
199	               "never claim to have added one yourself.";
200	        if (!m_network.empty()) {
201	            instructions << "\nThese printers are on the network right now, and the panel already lists them with their own buttons, so do "
202	                            "not repeat them in your opening: ";
203	            for (const DiscoveredPrinter& found : m_network)
204	                instructions << found.name << " (" << found.stable_id << ") ";
205	        }
206	    } else {
207	        instructions << "The person already has this printer set up: " << m_printer_fact.value;
208	        if (!m_nozzle.value.empty())
209	            instructions << ", a " << m_nozzle.value << " nozzle";
210	        if (!m_plate.value.empty())
211	            instructions << ", the " << m_plate.value << " plate";
212	        if (!m_filament.value.empty())
213	            instructions << ", " << m_filament.value;
214	        instructions
215	            << (m_printer.connected ? ", connected to this app." : ", not connected to this app.")
216	            << "\nThey tell you what changed on it, or ask about it: nozzle, plate, spools, connection. Apply a change with printer_change; "
217	               "it asks the person to approve that change on a card, so say what it now is only after the result says it was applied.\n"
218	               "The plate belongs to each project rather than to the printer, so a plate change is made in the project; say so if it comes up.";
219	    }
220	    profile.instructions = instructions.str();
221	    return profile;
222	}
