224	std::string PrinterConversation::opening_message() const
225	{
226	    // The opening is the panel's own copy rather than a generated turn: it is
227	    // the same promise every time the panel opens, and a session that begins
228	    // with a network round trip would open on an empty thread.
229	    if (m_mode == ConversationMode::Change) {
230	        const std::string name = m_printer_fact.value.empty() ? std::string("this printer") : m_printer_fact.value;
231	        return "This is the " + name +
232	               ". Tell me what changed on it, or ask anything about it: nozzle, plate, spools, connection. A photo of the part works too.";
233	    }
234	    return "What printer do you have? Say it any way: \"bambu a1 mini\", \"the ender with the touchscreen\", \"not sure, the small one\".";
235	}
