237	json PrinterConversation::state_json() const
238	{
239	    json chips = m_chips;
240	    // The person can always add the printer the agent has drawn; the chip is
241	    // the approval for it, so it leads the row whatever else is offered.
242	    if (m_proposal.valid) {
243	        json add{{"id", "add"}, {"label", "Add this printer"}, {"style", "primary"}, {"action", "add"}};
244	        chips.insert(chips.begin(), add);
245	        chips.push_back(json{{"id", "reject"}, {"label", "Not this one"}, {"style", "plain"}, {"say", "Not this one"}});
246	    }
247	    return json{{"mode", m_mode == ConversationMode::Add ? "add" : "change"},
248	                {"caption", m_mode == ConversationMode::Add ? "NEW PRINTER" : "PRINTER"},
249	                {"facts", json{{"printer", fact_json(m_printer_fact)},
250	                               {"nozzle", fact_json(m_nozzle)},
251	                               {"plate", fact_json(m_plate)},
252	                               {"filament", fact_json(m_filament)}}},
253	                {"blocks", m_blocks},
254	                {"chips", std::move(chips)},
255	                {"chipHint", m_chip_hint},
256	                {"placeholder", m_placeholder}};
257	}
