267	
268	ToolExecutionCoordinator::ExtensionResult PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
269	{
270	    ToolExecutionCoordinator::ExtensionResult result;
271	    if (handler != ToolHandler::PrinterCatalogSearch && handler != ToolHandler::PrinterPropose &&
272	        handler != ToolHandler::PrinterSuggest && handler != ToolHandler::PrinterChange)
273	        return result;
274	
275	    result.handled = true;
276	    const json arguments = json::parse(activity.arguments_json, nullptr, false);
277	    if (!arguments.is_object()) {
278	        result.error = ToolError{"invalid_arguments", "The printer tool arguments are invalid."};
279	        return result;
280	    }
281	
282	    std::optional<ToolError> error;
283	    json output;
284	    switch (handler) {
285	    case ToolHandler::PrinterCatalogSearch: output = search_catalog(arguments); break;
286	    case ToolHandler::PrinterPropose: output = propose(arguments, error); break;
287	    case ToolHandler::PrinterSuggest: output = suggest(arguments); break;
288	    default: output = change(arguments, error); break;
289	    }
290	    if (error) {
291	        result.error = std::move(error);
292	        return result;
293	    }
294	    // Everything the tools draw lands in the same place: the panel's own
295	    // state, pushed once per call.
296	    if (handler != ToolHandler::PrinterCatalogSearch) {
297	        if (handler == ToolHandler::PrinterPropose && !m_blocks.empty())
298	            m_blocks.back()["afterMessageId"] = activity.correlation_id;
299	        m_host.session_changed();
300	    }
301	    result.result_json = output.dump();
302	    return result;
303	}
304	
305	json PrinterConversation::search_catalog(const json& arguments)
306	{
307	    const std::string query = arguments.value("query", std::string());
308	    const std::size_t limit = std::min<std::size_t>(arguments.value("limit", 5), 8);
309	
310	    json items = json::array();
311	    for (const CatalogPrinter& printer : m_backend.search_catalog(query, limit)) {
312	        json nozzles = json::array();
313	        for (double nozzle : printer.nozzles)
314	            nozzles.push_back(nozzle);
315	        items.push_back(json{{"catalogId", printer.id},
316	                             {"vendor", printer.vendor_name},
317	                             {"model", printer.model_name},
318	                             {"buildVolume", printer.build_volume},
319	                             {"nozzles", std::move(nozzles)},
320	                             {"plate", printer.default_plate},
321	                             {"material", printer.default_material}});
322	        if (catalog_entry(printer.id) == nullptr)
323	            m_catalog.push_back(printer);
324	    }
325	    return json{{"items", std::move(items)}};
326	}
327	
328	json PrinterConversation::propose(const json& arguments, std::optional<ToolError>& error)
329	{
330	    const json& printers = arguments.at("printers");
331	    if (printers.empty() || printers.size() > kMaximumCandidates) {
332	        error = ToolError{"invalid_arguments", "Propose one printer, or two or three when they are hard to tell apart."};
333	        return {};
334	    }
335	
336	    json cards = json::array();
337	    std::vector<const CatalogPrinter*> proposed;
338	    for (const json& entry : printers) {
339	        const std::string catalog_id = entry.value("catalogId", std::string());
340	        const std::string device_id  = entry.value("deviceId", std::string());
341	        const CatalogPrinter* known  = catalog_entry(catalog_id);
342	        if (known == nullptr) {
343	            error = ToolError{"unknown_printer",
344	                              "\"" + catalog_id + "\" is not a printer from printer_catalog_search. Search first, then propose."};
345	            return {};
346	        }
347	        proposed.push_back(known);
348	        cards.push_back(json{{"catalogId", known->id},
349	                             {"deviceId", device_id},
350	                             {"name", known->vendor_name + " " + known->model_name},
351	                             {"subline", entry.value("subline", known->build_volume)},
352	                             {"picture", picture_data_url(known->picture)},
353	                             {"action", printers.size() == 1 ? "add" : "choose"}});
354	    }
355	
356	    m_blocks.push_back(json{{"id", "b" + std::to_string(m_next_block++)},
357	                            {"seq", m_blocks.size() + 1},
358	                            {"afterMessageId", ""},
359	                            {"kind", "printers"},
360	                            {"printers", std::move(cards)}});
361	
362	    // A nozzle of zero is "nothing was said about it", which for a printer
363	    // nobody has changed is the 0.4 mm it ships with.
364	    const double      stated   = arguments.value("nozzle", 0.);
365	    const double      nozzle   = stated > 0. ? stated : 0.4;
366	    const std::string plate    = arguments.value("plate", std::string());
367	    const std::string filament = arguments.value("filament", std::string());
368	    const std::string state    = arguments.value("provenance", std::string("assumed"));
369	
370	    if (proposed.size() == 1) {
371	        const CatalogPrinter& printer = *proposed.front();
372	        const json&           entry   = printers.front();
373	        // A nozzle this model has no profile for cannot be saved, and the
374	        // person should hear that now rather than when they tap Add.
375	        if (!printer.nozzles.empty() &&
376	            std::find(printer.nozzles.begin(), printer.nozzles.end(), nozzle) == printer.nozzles.end()) {
377	            std::string sizes;
378	            for (double size : printer.nozzles)
379	                sizes += (sizes.empty() ? "" : ", ") + nozzle_text(size);
380	            m_blocks.erase(m_blocks.end() - 1);
381	            error = ToolError{"unknown_nozzle", "The " + printer.model_name + " ships " + sizes + " nozzles, not " +
382	                                                    nozzle_text(nozzle) + "."};
383	            return {};
384	        }
385	        m_proposal = PrinterProposal{true,
386	                                     printer.vendor_id,
387	                                     printer.model_id,
388	                                     printer.vendor_name + " " + printer.model_name,
389	                                     variant_text(nozzle),
390	                                     printer.default_material,
391	                                     entry.value("deviceId", std::string()),
392	                                     printer.picture,
393	                                     entry.value("subline", printer.build_volume)};
394	        m_printer_fact = {m_proposal.model_name, "settled", {}};
395	        m_nozzle       = {nozzle_text(nozzle), state, {}};
396	        m_plate        = {plate.empty() ? printer.default_plate : plate, state, {}};
397	        m_filament     = {filament.empty() ? std::string("PLA") : filament, state, {}};
398	    } else {
399	        // Nothing is settled while two printers are still on the table.
400	        m_proposal     = {};
401	        m_printer_fact = m_nozzle = m_plate = m_filament = {};
402	    }
403	    return json{{"proposed", proposed.size()}};
