422	json PrinterConversation::change(const json& arguments, std::optional<ToolError>& error)
423	{
424	    if (m_mode != ConversationMode::Change || m_printer.name.empty()) {
425	        error = ToolError{"no_printer", "This session is not about a printer that exists yet."};
426	        return {};
427	    }
428	
429	    ChangePrinterRequest request;
430	    request.name = m_printer.name;
431	    if (arguments.contains("nozzle") && arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() > 0.)
432	        request.nozzle = arguments["nozzle"].get<double>();
433	    if (arguments.contains("accessCode") && !arguments["accessCode"].get<std::string>().empty())
434	        request.access_code = arguments["accessCode"].get<std::string>();
435	    if (arguments.contains("spools") && arguments["spools"].is_array()) {
436	        std::vector<PrinterSpool> spools;
437	        for (const json& spool : arguments["spools"])
438	            spools.push_back(PrinterSpool{spool.value("name", std::string()), spool.value("material", std::string()),
439	                                          spool.value("colour", std::string())});
440	        request.spools = std::move(spools);
441	    }
442	    if (!request.nozzle && !request.access_code && !request.spools) {
443	        error = ToolError{"nothing_to_change", "Name the nozzle, the spools or the access code that changed."};
444	        return {};
445	    }
446	
447	    SavedPrinter      changed;
448	    const std::string problem = m_backend.change_printer(request, changed);
449	    if (!problem.empty()) {
450	        error = ToolError{"change_failed", problem};
451	        return {};
452	    }
453	
454	    const double was = m_printer.nozzle;
455	    m_printer        = changed;
456	    read_saved_printer();
457	    if (request.nozzle && was != changed.nozzle)
458	        m_nozzle.provenance = "changed";
459	    if (request.spools)
460	        m_filament.provenance = "changed";
461	    m_host.printers_changed();
462	
463	    return json{{"printer", changed.name}, {"nozzle", changed.nozzle}, {"connected", changed.connected}};
464	}
