468	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
469	{
470	    if (type != "printer_action")
471	        return false;
472	
473	    const std::string action = payload.value("action", std::string());
474	    const std::string id     = payload.value("id", std::string());
475	    if (action == "close")
476	        m_host.close_panel();
477	    else if (action == "manual_setup") {
478	        if (m_mode == ConversationMode::Add) {
479	            // The wizard takes over from here; whatever it installed is on
480	            // the printer list the panel returns to.
481	            m_backend.run_manual_setup();
482	            m_host.printers_changed();
483	            m_host.close_panel();
484	        } else {
485	            // OrcaSlicer's own printer settings, as "Printer settings…" did
486	            // before this panel existed. It closes back into this session,
487	            // which restates the printer as it now is.
488	            m_backend.open_printer_settings(m_printer_name);
489	            read_saved_printer();
490	            m_host.printers_changed();
491	            m_host.session_changed();
492	        }
493	    } else if (action == "add")
494	        add_proposed_printer(payload.value("accessCode", std::string()));
495	    else if (action == "network_pick")
496	        use_network_printer(id);
497	    else if (action == "candidate_pick")
498	        choose_candidate(id);
499	    return true;
500	}
