30	std::vector<std::string> split(const std::string& value, char delimiter)
31	{
32	    std::vector<std::string> result;
33	    std::istringstream input(value);
34	    std::string part;
35	    while (std::getline(input, part, delimiter))
36	        if (!part.empty()) result.push_back(part);
37	    return result;
38	}
