48	json resolve_machine(const std::string& name, const std::map<std::string, json>& machines,
49	                     std::set<std::string>& visiting)
50	{
51	    const auto found = machines.find(name);
52	    if (found == machines.end() || !visiting.insert(name).second)
53	        return json::object();
54	    json resolved = json::object();
55	    const std::string parent = found->second.value("inherits", "");
56	    if (!parent.empty())
57	        resolved = resolve_machine(parent, machines, visiting);
58	    for (const auto& item : found->second.items())
59	        resolved[item.key()] = item.value();
60	    visiting.erase(name);
61	    return resolved;
62	}
