64	std::string build_volume(const json& machine)
65	{
66	    const auto area = machine.value("printable_area", json::array());
67	    double min_x = 0., min_y = 0., max_x = 0., max_y = 0.;
68	    bool first = true;
69	    for (const auto& point : area) {
70	        if (!point.is_string()) continue;
71	        const auto values = split(point.get<std::string>(), 'x');
72	        if (values.size() != 2) continue;
73	        try {
74	            const double x = std::stod(values[0]);
75	            const double y = std::stod(values[1]);
76	            if (first) { min_x = max_x = x; min_y = max_y = y; first = false; }
77	            else { min_x = std::min(min_x, x); max_x = std::max(max_x, x);
78	                   min_y = std::min(min_y, y); max_y = std::max(max_y, y); }
79	        } catch (const std::exception&) {}
80	    }
81	    if (first) return {};
82	    const std::string height = first_string(machine.value("printable_height", json()));
