96	PrinterCatalog PrinterCatalog::load(const std::string& resources_directory)
97	{
98	    const fs::path profiles = fs::path(resources_directory) / "profiles";
99	    std::vector<PrinterCandidate> candidates;
100	    for (const fs::directory_entry& vendor_entry : fs::directory_iterator(profiles)) {
101	        if (!vendor_entry.is_regular_file() || vendor_entry.path().extension() != ".json") continue;
102	        const std::string vendor_id = vendor_entry.path().stem().string();
103	        const json index = read_json(vendor_entry.path());
104	        if (!index.contains("machine_model_list") || !index.contains("machine_list")) continue;
105	        const std::string vendor_name = index.value("name", vendor_id);
106	        const fs::path vendor_dir = profiles / vendor_id;
107	
108	        std::map<std::string, json> machines;
109	        for (const auto& entry : index["machine_list"]) {
110	            const std::string name = entry.value("name", "");
111	            const std::string sub_path = entry.value("sub_path", "");
112	            if (!name.empty() && !sub_path.empty()) machines.emplace(name, read_json(vendor_dir / sub_path));
113	        }
114	
115	        for (const auto& entry : index["machine_model_list"]) {
116	            const std::string sub_path = entry.value("sub_path", "");
117	            if (sub_path.empty()) continue;
118	            const json model = read_json(vendor_dir / sub_path);
119	            const std::string model_name = model.value("name", entry.value("name", ""));
120	            const std::string model_id = model_name;
121	            const std::string device_model = model.value("model_id", "");
122	            const auto variants = split(first_string(model.value("nozzle_diameter", json())), ';');
123	            const auto materials = split(first_string(model.value("default_materials", json())), ';');
124	            const std::string plate = first_string(model.value("default_bed_type", json()));
125	            fs::path artwork = vendor_dir / (model_name + "_cover.png");
126	            if (!fs::exists(artwork)) artwork.clear();
127	
128	            for (const std::string& variant : variants) {
129	                const std::string preset_name = model_name + " " + variant + " nozzle";
130	                std::set<std::string> visiting;
131	                const json machine = resolve_machine(preset_name, machines, visiting);
132	                if (machine.empty()) continue; // not an installable variant
133	                PrinterCandidate candidate;
134	                candidate.id = "printer-" + std::to_string(candidates.size());
135	                candidate.vendor_id = vendor_id;
136	                candidate.vendor_name = vendor_name;
137	                candidate.model_id = model_id;
138	                candidate.model_name = model_name;
139	                candidate.device_model_id = device_model;
140	                candidate.variant = variant;
141	                candidate.preset_name = preset_name;
142	                candidate.build_volume = build_volume(machine);
143	                candidate.default_material = !materials.empty() ? materials.front()
144	                    : first_string(machine.value("default_filament_profile", json()));
145	                candidate.default_plate = plate;
146	                candidate.artwork_path = artwork.string();
147	                candidates.push_back(std::move(candidate));
148	            }
149	        }
150	    }
151	    if (candidates.empty())
152	        throw std::runtime_error("No installable printer profiles were found.");
153	    return PrinterCatalog(std::move(candidates));
154	}
