228	        for (const CatalogPrinter& printer : m_catalog)
229	            instructions << printer.id << " | " << (printer.build_volume.empty() ? "?" : printer.build_volume) << "\n";
230	        if (!m_network.empty()) {
231	            instructions << "\nThese printers are on the network right now, and the panel already lists them with their own buttons, so do "
232	                            "not repeat them in your opening: ";
233	            for (const DiscoveredPrinter& found : m_network)
234	                instructions << found.name << " (" << found.stable_id << ") ";
235	        }
236	    } else {
237	        instructions << "The person already has this printer set up: " << m_printer_fact.value;
238	        if (!m_nozzle.value.empty())
239	            instructions << ", a " << m_nozzle.value << " nozzle";
240	        if (!m_plate.value.empty())
241	            instructions << ", the " << m_plate.value << " plate";
242	        if (!m_filament.value.empty())
243	            instructions << ", " << m_filament.value;
244	        instructions
245	            << (m_printer.connected ? ", connected to this app." : ", not connected to this app.")
246	            << "\nThey tell you what changed on it, or ask about it: nozzle, plate, spools, connection. Apply a change with printer_change; "
247	               "it asks the person to approve that change on a card, so say what it now is only after the result says it was applied.\n"
248	               "The plate belongs to each project rather than to the printer, so a plate change is made in the project; say so if it comes up.";
249	    }
250	    profile.instructions = instructions.str();
251	    return profile;
252	}
