254	std::string PrinterConversation::opening_message() const
255	{
256	    // The opening is the panel's own copy rather than a generated turn: it is
257	    // the same promise every time the panel opens, and a session that begins
258	    // with a network round trip would open on an empty thread.
259	    if (m_mode == ConversationMode::Change) {
260	        const std::string name = m_printer_fact.value.empty() ? std::string("this printer") : m_printer_fact.value;
261	        return "This is the " + name +
262	               ". Tell me what changed on it, or ask anything about it: nozzle, plate, spools, connection. A photo of the part works too.";
263	    }
