267	json PrinterConversation::state_json() const
268	{
269	    json chips = m_chips;
270	    // The person can always add the printer the agent has drawn; the chip is
271	    // the approval for it, so it leads the row whatever else is offered.
272	    if (m_proposal.valid) {
273	        json add{{"id", "add"}, {"label", "Add this printer"}, {"style", "primary"}, {"action", "add"}};
274	        chips.insert(chips.begin(), add);
275	        chips.push_back(json{{"id", "reject"}, {"label", "Not this one"}, {"style", "plain"}, {"say", "Not this one"}});
276	    }
277	    return json{{"mode", m_mode == ConversationMode::Add ? "add" : "change"},
278	                {"caption", m_mode == ConversationMode::Add ? "NEW PRINTER" : "PRINTER"},
279	                {"facts", json{{"printer", fact_json(m_printer_fact)},
280	                               {"nozzle", fact_json(m_nozzle)},
281	                               {"plate", fact_json(m_plate)},
282	                               {"filament", fact_json(m_filament)}}},
283	                {"blocks", m_blocks},
284	                {"chips", std::move(chips)},
285	                {"chipHint", m_chip_hint},
286	                {"placeholder", m_placeholder}};
