296	// -- The session's tools ----------------------------------------------------
297	
298	ToolExecutionCoordinator::ExtensionResult PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
299	{
300	    ToolExecutionCoordinator::ExtensionResult result;
301	    if (handler != ToolHandler::PrinterIdentify && handler != ToolHandler::PrinterSuggest &&
302	        handler != ToolHandler::PrinterChange)
303	        return result;
304	
305	    result.handled = true;
306	    const json arguments = json::parse(activity.arguments_json, nullptr, false);
307	    if (!arguments.is_object()) {
308	        result.error = ToolError{"invalid_arguments", "The printer tool arguments are invalid."};
309	        return result;
310	    }
311	
312	    std::optional<ToolError> error;
313	    json output;
314	    switch (handler) {
315	    case ToolHandler::PrinterIdentify: output = identify(arguments, error); break;
316	    case ToolHandler::PrinterSuggest: output = suggest(arguments); break;
317	    default: output = change(arguments, error); break;
318	    }
319	    if (error) {
320	        result.error = std::move(error);
321	        return result;
322	    }
323	    // Everything the tools draw lands in the same place: the panel's own
324	    // state, pushed once per call.
325	    if (handler == ToolHandler::PrinterIdentify && !m_blocks.empty())
326	        m_blocks.back()["afterMessageId"] = activity.correlation_id;
327	    m_host.session_changed();
328	    result.result_json = output.dump();
329	    return result;
330	}
331	
332	json PrinterConversation::identify(const json& arguments, std::optional<ToolError>& error)
333	{
334	    const std::string action = arguments.at("action").get<std::string>();
335	    const json&       ids    = arguments.at("catalogIds");
336	
337	    json cards = json::array();
338	    std::vector<const CatalogPrinter*> shown;
339	    for (const json& entry : ids) {
340	        const std::string     catalog_id = entry.get<std::string>();
341	        const CatalogPrinter* known      = catalog_entry(catalog_id);
342	        if (known == nullptr) {
343	            error = ToolError{"unknown_printer",
344	                              "\"" + catalog_id + "\" is not on the printer list this session was given. Copy the catalogId exactly."};
345	            return {};
346	        }
347	        shown.push_back(known);
348	        cards.push_back(json{{"catalogId", known->id},
349	                             {"deviceId", ""},
350	                             {"name", known->vendor_name + " " + known->model_name},
351	                             {"subline", known->build_volume},
352	                             {"picture", picture_data_url(known->picture)},
353	                             {"action", action == "propose" && shown.size() == 1 && ids.size() == 1 ? "add" : "choose"}});
354	    }
355	
356	    // Only a single confident "propose" settles anything; a question -- asked
357	    // outright, or a propose that is still two or three cards -- leaves the
358	    // pinned card as it was, and unsupported clears it.
359	    if (action != "propose" || shown.size() != 1) {
360	        m_proposal     = {};
361	        m_printer_fact = m_nozzle = m_plate = m_filament = {};
362	        if (!cards.empty())
363	            m_blocks.push_back(json{{"id", "b" + std::to_string(m_next_block++)},
364	                                    {"seq", m_blocks.size() + 1},
365	                                    {"afterMessageId", ""},
366	                                    {"kind", "printers"},
367	                                    {"printers", std::move(cards)}});
368	        return json{{"action", action}, {"shown", shown.size()}};
369	    }
370	
371	    const CatalogPrinter& printer = *shown.front();
372	    // A nozzle of zero is "nothing was said about it", which for a printer
373	    // nobody has changed is the 0.4 mm it ships with.
374	    const double      stated   = arguments.value("nozzle", 0.);
375	    const double      nozzle   = stated > 0. ? stated : 0.4;
376	    const std::string plate    = arguments.value("plate", std::string());
377	    const std::string filament = arguments.value("filament", std::string());
378	    const std::string state    = arguments.value("provenance", std::string("assumed"));
379	
380	    // A nozzle this model has no profile for cannot be saved, and the person
381	    // should hear that now rather than when they tap Add.
382	    if (!printer.nozzles.empty() &&
383	        std::find(printer.nozzles.begin(), printer.nozzles.end(), nozzle) == printer.nozzles.end()) {
384	        std::string sizes;
385	        for (double size : printer.nozzles)
386	            sizes += (sizes.empty() ? "" : ", ") + nozzle_text(size);
387	        error = ToolError{"unknown_nozzle",
388	                          "The " + printer.model_name + " ships " + sizes + " nozzles, not " + nozzle_text(nozzle) + "."};
389	        return {};
390	    }
391	
392	    m_blocks.push_back(json{{"id", "b" + std::to_string(m_next_block++)},
393	                            {"seq", m_blocks.size() + 1},
394	                            {"afterMessageId", ""},
395	                            {"kind", "printers"},
396	                            {"printers", std::move(cards)}});
397	
398	    // The device id is never asked of the model: when this proposal answers
399	    // "Use this" on a network find, the app already knows which one.
400	    const std::string device_id = m_pending_device_id;
401	    m_pending_device_id.clear();
402	
403	    m_proposal = PrinterProposal{true,
404	                                 printer.vendor_id,
405	                                 printer.model_id,
406	                                 printer.vendor_name + " " + printer.model_name,
407	                                 variant_text(nozzle),
408	                                 printer.default_material,
409	                                 device_id,
410	                                 printer.picture,
411	                                 printer.build_volume};
412	    m_printer_fact = {m_proposal.model_name, "settled", {}};
413	    m_nozzle       = {nozzle_text(nozzle), state, {}};
414	    m_plate        = {plate.empty() ? printer.default_plate : plate, state, {}};
415	    m_filament     = {filament.empty() ? std::string("PLA") : filament, state, {}};
416	    return json{{"action", "propose"}, {"shown", 1}};
417	}
418	
419	json PrinterConversation::suggest(const json& arguments)
420	{
421	    m_chips = json::array();
422	    for (const json& action : arguments.at("actions")) {
423	        const std::string label = action.value("label", std::string());
424	        if (label.empty())
425	            continue;
426	        m_chips.push_back(json{{"id", "s" + std::to_string(m_chips.size() + 1)},
427	                               {"label", label},
428	                               {"style", action.value("suggested", false) ? "suggested" : "plain"},
429	                               {"say", label}});
430	    }
431	    m_chip_hint = arguments.value("hint", std::string());
432	    return json{{"offered", m_chips.size()}};
433	}
434	
435	json PrinterConversation::change(const json& arguments, std::optional<ToolError>& error)
436	{
437	    if (m_mode != ConversationMode::Change || m_printer.name.empty()) {
438	        error = ToolError{"no_printer", "This session is not about a printer that exists yet."};
439	        return {};
440	    }
441	
442	    ChangePrinterRequest request;
443	    request.name = m_printer.name;
444	    if (arguments.contains("nozzle") && arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() > 0.)
445	        request.nozzle = arguments["nozzle"].get<double>();
446	    if (arguments.contains("accessCode") && !arguments["accessCode"].get<std::string>().empty())
447	        request.access_code = arguments["accessCode"].get<std::string>();
448	    if (arguments.contains("spools") && arguments["spools"].is_array()) {
449	        std::vector<PrinterSpool> spools;
450	        for (const json& spool : arguments["spools"])
451	            spools.push_back(PrinterSpool{spool.value("name", std::string()), spool.value("material", std::string()),
452	                                          spool.value("colour", std::string())});
453	        request.spools = std::move(spools);
454	    }
455	    if (!request.nozzle && !request.access_code && !request.spools) {
456	        error = ToolError{"nothing_to_change", "Name the nozzle, the spools or the access code that changed."};
457	        return {};
458	    }
459	
460	    SavedPrinter      changed;
461	    const std::string problem = m_backend.change_printer(request, changed);
462	    if (!problem.empty()) {
463	        error = ToolError{"change_failed", problem};
464	        return {};
465	    }
466	
467	    const double was = m_printer.nozzle;
468	    m_printer        = changed;
469	    read_saved_printer();
470	    if (request.nozzle && was != changed.nozzle)
471	        m_nozzle.provenance = "changed";
472	    if (request.spools)
473	        m_filament.provenance = "changed";
474	    m_host.printers_changed();
475	
476	    return json{{"printer", changed.name}, {"nozzle", changed.nozzle}, {"connected", changed.connected}};
477	}
