479	// -- Taps on the panel's own cards -------------------------------------------
480	
481	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
482	{
483	    if (type != "printer_action")
484	        return false;
485	
486	    const std::string action = payload.value("action", std::string());
487	    const std::string id     = payload.value("id", std::string());
488	    if (action == "close")
489	        m_host.close_panel();
490	    else if (action == "manual_setup") {
491	        if (m_mode == ConversationMode::Add) {
492	            // The wizard takes over from here; whatever it installed is on
493	            // the printer list the panel returns to.
494	            m_backend.run_manual_setup();
495	            m_host.printers_changed();
496	            m_host.close_panel();
497	        } else {
498	            // OrcaSlicer's own printer settings, as "Printer settings…" did
499	            // before this panel existed. It closes back into this session,
500	            // which restates the printer as it now is.
501	            m_backend.open_printer_settings(m_printer_name);
502	            read_saved_printer();
503	            m_host.printers_changed();
504	            m_host.session_changed();
505	        }
506	    } else if (action == "add")
507	        add_proposed_printer(payload.value("accessCode", std::string()));
508	    else if (action == "network_pick")
509	        use_network_printer(id);
510	    else if (action == "candidate_pick")
511	        choose_candidate(id);
512	    return true;
513	}
514	
515	void PrinterConversation::add_proposed_printer(const std::string& access_code)
516	{
517	    if (!m_proposal.valid)
518	        return;
519	
520	    AddPrinterRequest request;
521	    request.vendor_id   = m_proposal.vendor_id;
522	    request.model_id    = m_proposal.model_id;
523	    request.variant     = m_proposal.variant;
524	    request.material    = m_proposal.material;
525	    request.name        = m_proposal.model_name;
526	    request.device_id   = m_proposal.device_id;
527	    request.access_code = access_code;
528	
529	    SavedPrinter      added;
530	    const std::string problem = m_backend.add_printer(request, added);
531	    if (!problem.empty()) {
532	        // One error at a time, in the thread, with what to do about it.
533	        m_host.post_note(problem);
534	        m_host.session_changed();
535	        return;
536	    }
537	    m_host.printers_changed();
538	    m_host.close_panel();
539	}
540	
541	void PrinterConversation::use_network_printer(const std::string& device_id)
542	{
543	    refresh_network();
544	    const auto found = std::find_if(m_network.begin(), m_network.end(),
545	                                    [&device_id](const DiscoveredPrinter& printer) { return printer.stable_id == device_id; });
546	    if (found == m_network.end()) {
547	        m_host.post_note("That printer is no longer on the network. Say which printer you have and I will set it up unconnected.");
548	        m_host.session_changed();
549	        return;
550	    }
551	
552	    m_host.post_note("\"Use this\" · " + found->stable_id);
553	    // printer_identify's next call names the device; the app links the two,
554	    // so the model is never asked to echo the id back.
555	    m_pending_device_id = found->stable_id;
556	
557	    std::ostringstream prompt;
558	    prompt << "The person tapped \"Use this\" on the printer found on the network. It reports itself as model id "
559	           << found->device_model_id << ", name \"" << found->name << "\", serial " << found->stable_id;
560	    if (found->nozzle_diameter > 0.)
561	        prompt << ", a " << nozzle_text(found->nozzle_diameter) << " nozzle";
562	    if (!found->ams_name.empty())
563	        prompt << ", " << found->ams_name << " with " << found->spools.size() << " spools";
564	    prompt << ", over " << (found->connection.empty() ? "the network" : found->connection)
565	           << ". Find that model on the printer list and call printer_identify to propose it alone, with these reported facts as "
566	              "settled rather than assumed, and say that nothing had to be assumed. Then say the person can keep it connected by "
567	              "entering its access code, which is under Settings > Network on the printer.";
568	    m_placeholder = "access code, optional";
569	    m_host.ask_agent(prompt.str());
570	}
571	
572	void PrinterConversation::choose_candidate(const std::string& catalog_id)
573	{
574	    const CatalogPrinter* chosen = catalog_entry(catalog_id);
575	    if (chosen == nullptr)
576	        return;
577	    m_host.ask_agent("The person tapped \"This one\" on " + chosen->vendor_name + " " + chosen->model_name + " (" + chosen->id +
578	                     "). Call printer_identify to propose that printer alone and say in one sentence what you assumed.");
579	}
