64	
65	    std::string add_printer(const AddPrinterRequest& request, SavedPrinter& result) override
66	    {
67	        added.push_back(request);
68	        if (!refusal.empty())
69	            return refusal;
70	        result.name = request.name;
71	        return {};
72	    }
